def icon(name, size=20, colour='currentColor', style=''):
    """One inline Material glyph, sized to the app's scale."""
    path = PATHS[name]
    extra = f' style="{style}"' if style else ''
    return (f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="{colour}" '
            f'aria-hidden="true"{extra}><path d="{path}"/></svg>')


if __name__ == '__main__':
    import sys
    name = sys.argv[1] if len(sys.argv) > 1 else None
    if name in PATHS:
        print(icon(name, int(sys.argv[2]) if len(sys.argv) > 2 else 20))
    else:
        print('available:', ', '.join(sorted(PATHS)))
